import json,re,sys
d=json.load(open('/tmp/vo.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        if n.get('type')=='text': out.append(n.get('text',''))
        elif n.get('type')=='paragraph': out.append('\n\nPARA: ')
        elif n.get('type')=='heading': out.append('\n\n## '+str(n.get('text','')))
        for v in n.values(): walk(v)
    elif isinstance(n,list):
        for v in n: walk(v)
walk(d.get('primaryContentSections'))
print(''.join(out))
" > /tmp/vo.txt; wc -c /tmp/vo.txt; grep -n -i "locale\|top-to-bottom\|group\|caption" /tmp/vo.txt
